public static List<TrackSampleTable> parseTraks(Atom.ContainerAtom moov, GaplessInfoHolder gaplessInfoHolder, long duration, @Nullable DrmInitData drmInitData, boolean ignoreEditLists, boolean isQuickTime, Function<@NullableType Track, @NullableType Track> modifyTrackFunction) throws ParserException {
  List<TrackSampleTable> trackSampleTables = new ArrayList<>();
  for (int i = 0; i < moov.containerChildren.size(); i++) {
    Atom.ContainerAtom atom = moov.containerChildren.get(i);
    if (atom.type != Atom.TYPE_trak) {
      continue;
    }
    try {
      @Nullable Track track = modifyTrackFunction.apply(parseTrak(atom, checkNotNull(moov.getLeafAtomOfType(Atom.TYPE_mvhd)), duration, drmInitData, ignoreEditLists, isQuickTime));
      if (track == null) {
        continue;
      }
      Atom.ContainerAtom stblAtom = checkNotNull(checkNotNull(checkNotNull(atom.getContainerAtomOfType(Atom.TYPE_mdia)).getContainerAtomOfType(Atom.TYPE_minf)).getContainerAtomOfType(Atom.TYPE_stbl));
      TrackSampleTable trackSampleTable = parseStbl(track, stblAtom, gaplessInfoHolder);
      trackSampleTables.add(trackSampleTable);
    } catch (IllegalArgumentException | IllegalStateException | IndexOutOfBoundsException | NullPointerException | NegativeArraySizeException e) {
      throw new ParserException(e);
    }
  }
  return trackSampleTables;
}
